package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.annotation.Propagation;
import java.math.BigDecimal;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Explicit short transactions surround immutable source capture and result persistence; HTTP/file I/O holds no locks. */
@Service
public class FinanceInvoiceAutomationService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;private final FinanceService finance;private final FinanceEvidenceService evidence;private final FinanceInvoiceAutomationGateway gateway;private final TransactionTemplate tx;
 public FinanceInvoiceAutomationService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit,FinanceService finance,FinanceEvidenceService evidence,FinanceInvoiceAutomationGateway gateway,PlatformTransactionManager manager){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;this.finance=finance;this.evidence=evidence;this.gateway=gateway;tx=new TransactionTemplate(manager);}
 private TenantPrincipal principal(){var p=access.principal();database.apply(p.tenantId());return p;}
 public Map<String,Object> context(){access.requireAnyPermission("finance.submit","finance.read","finance.review");return gateway.context();}
 private Map<String,Object> intake(UUID id){return finance.intakeDetail(id);}
 private Map<String,Object> snapshot(Map<String,Object> intake){var s=new LinkedHashMap<String,Object>();s.put("invoiceCode",FinanceRules.digits(Objects.toString(intake.get("invoiceCode"),"")));s.put("invoiceNumber",FinanceRules.digits(Objects.toString(intake.get("invoiceNumber"),"")));s.put("amount",intake.get("amount")==null?null:amount(intake.get("amount")).setScale(2).toPlainString());s.put("buyerTaxNumber",FinanceRules.taxNumber(Objects.toString(intake.get("buyerTaxNumber"),"")));return s;}
 public Map<String,Object> jobs(UUID intakeId){return tx.execute(s->{var p=principal();var current=intake(intakeId);var rows=jdbc.queryForList("select j.*,p.id as proof_id,p.external_reference,p.outcome as proof_outcome,p.response,p.received_at from fia_job j left join fia_proof p on p.tenant_id=j.tenant_id and p.job_id=j.id where j.tenant_id=:tenant and j.intake_id=:intake order by j.created_at desc limit 100",base(p).addValue("intake",intakeId));var result=new ArrayList<Map<String,Object>>();for(var row:rows){row.put("matchesCurrentSource",Objects.equals(current.get("sha256"),row.get("source_sha256"))&&snapshot(current).equals(map(row.get("invoice_snapshot"))));result.add(row);}return output(Map.of("items",result,"intakeVersion",current.get("version"),"sourceSha256",Objects.toString(current.get("sha256"),"")));});}
 @Transactional(propagation=Propagation.NOT_SUPPORTED)
 public Map<String,Object> start(UUID intakeId,FinanceInvoiceAutomationModels.Start in){access.requireAnyPermission("finance.submit","finance.read","finance.review");if(!Set.of("OCR","VERIFY").contains(in.operation())||!in.allowExternalTransfer()||in.consentNote()==null||in.consentNote().isBlank())throw bad("需明确操作类型和本次原件/验证资料外传授权");if(!gateway.ready(in.operation()))return gateway.call(in.operation(),in.requestId(),Map.of(),false);
  Map<String,Object> frozen=tx.execute(s->{var p=principal();var current=intake(intakeId);if(!Boolean.TRUE.equals(current.get("canEdit")))access.requirePermission("finance.review");if(((Number)current.get("version")).intValue()!=in.expectedIntakeVersion()||!Objects.equals(current.get("sha256"),in.sourceSha256()))throw conflict("收票内容或原件版本已变化，外传前请重新检查");if(in.operation().equals("VERIFY")){if(!Boolean.TRUE.equals(current.get("confirmed"))||current.get("amount")==null||Objects.toString(current.get("buyerTaxNumber"),"").isBlank())throw bad("外部验真前先对照原件确认票号、金额及购买方税号");FinanceRules.invoiceKey(current.get("invoiceCode").toString(),current.get("invoiceNumber").toString());}var b=base(p).addValue("id",in.requestId()).addValue("intake",intakeId);String hash=FinanceService.hash(json(Map.of("intake",intakeId,"command",in,"fields",snapshot(current))));var old=jdbc.queryForList("select * from fia_job where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("request_hash")))throw conflict("请求号已绑定其他资料或授权内容");return Map.<String,Object>of("replay",true);}
   jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,0))",base(p).addValue("key",p.tenantId()+":invoice-job:"+intakeId+":"+in.operation()),Object.class);if(jdbc.queryForObject("select count(*) from fia_job where tenant_id=:tenant and intake_id=:intake and operation=:op and status in ('PENDING','UNKNOWN')",b.addValue("op",in.operation()),Integer.class)>0)throw conflict("该原件已有未确定结果的同类请求，请查询原请求，不重复外传");b.addValue("hotel",current.get("hotelId")).addValue("version",current.get("version")).addValue("sha",in.sourceSha256()).addValue("snapshot",json(snapshot(current))).addValue("hash",hash).addValue("note",in.consentNote()).addValue("provider",gateway.provider());jdbc.update("insert into fia_job(id,tenant_id,intake_id,hotel_id,operation,intake_version,source_sha256,invoice_snapshot,request_hash,consent_note,consented_by,provider) values(:id,:tenant,:intake,:hotel,:op,:version,:sha,cast(:snapshot as jsonb),:hash,:note,:actor,:provider)",b);audit.record("FINANCE_INVOICE_EXTERNAL_CONSENT","FIA_JOB",in.requestId(),json(Map.of("operation",in.operation(),"intakeId",intakeId,"sourceSha256",in.sourceSha256(),"intakeVersion",in.expectedIntakeVersion(),"provider",gateway.provider())));return current;});
  if(Boolean.TRUE.equals(frozen.get("replay")))return jobs(intakeId);
  boolean attempted=false;try{var original=evidence.downloadIntake(intakeId);byte[] bytes;try(var stream=original.resource().getInputStream()){bytes=stream.readNBytes(20*1024*1024+1);}if(bytes.length>20*1024*1024||!FinanceService.hash(bytes).equals(in.sourceSha256()))throw conflict("受保护原件内容与本次授权哈希不同，已停止外传");var payload=new LinkedHashMap<String,Object>();payload.put("requestId",in.requestId().toString());payload.put("operation",in.operation());payload.put("sourceSha256",in.sourceSha256());payload.put("invoiceFields",snapshot(frozen));payload.put("mediaType",original.mediaType());if(in.operation().equals("OCR"))payload.put("originalBase64",Base64.getEncoder().encodeToString(bytes));attempted=true;var response=gateway.call(in.operation(),in.requestId(),payload,false);return finish(intakeId,in.requestId(),response);}catch(RuntimeException e){if(attempted)unknown(in.requestId());else failedBeforeTransmission(in.requestId());throw e;}catch(Exception e){if(attempted)unknown(in.requestId());else failedBeforeTransmission(in.requestId());throw bad("原件读取失败，未替换原始资料，请检查保护存储");}
 }
 @Transactional(propagation=Propagation.NOT_SUPPORTED)
 public Map<String,Object> refresh(UUID intakeId,UUID jobId){var job=tx.execute(s->{var p=principal();intake(intakeId);var row=job(p,intakeId,jobId,false);if(!p.actorId().equals(id(row.get("consented_by"))))access.requirePermission("finance.review");return row;});if(Set.of("SUCCEEDED","FAILED").contains(job.get("status")))return jobs(intakeId);var response=gateway.call(job.get("operation").toString(),jobId,Map.of(),true);return finish(intakeId,jobId,response);}
 private Map<String,Object> finish(UUID intakeId,UUID jobId,Map<String,Object> response){return tx.execute(s->{var p=principal();var current=intake(intakeId);var job=job(p,intakeId,jobId,true);if(Set.of("SUCCEEDED","FAILED").contains(job.get("status")))return jobs(intakeId);String outcome=Objects.toString(response.get("status"),"");if(outcome.equals("PENDING")||outcome.equals("UNKNOWN")){unknown(jobId);return jobs(intakeId);}if(!Objects.equals(job.get("source_sha256"),response.get("sourceSha256")))throw bad("服务结果未绑定原始文件哈希，不能作为OCR/验真证明");String reference=Objects.toString(response.get("externalReference"),"");if(reference.isBlank()||reference.length()>180||!Objects.equals(response.get("provider"),job.get("provider")))throw bad("外部结果缺少可信提供方或请求回执编号");String operation=job.get("operation").toString();if(operation.equals("OCR")){if(!outcome.equals("CANDIDATES"))throw bad("OCR服务没有返回候选结果，不能标记完成");candidate(map(response.get("candidates")));}else{if(!Set.of("VERIFIED","NOT_FOUND","INVALID","INCONCLUSIVE").contains(outcome))throw bad("未知外部验证状态");if(!snapshot(map(response.get("invoiceFields"))).equals(map(job.get("invoice_snapshot"))))throw bad("验真回执的票号、金额或税号与本次请求不一致");}
   var proof=new LinkedHashMap<>(response);proof.remove("originalBase64");if(json(proof).length()>250000)throw bad("外部证明超过允许长度");boolean matches=Objects.equals(current.get("sha256"),job.get("source_sha256"))&&snapshot(current).equals(map(job.get("invoice_snapshot")));var b=base(p).addValue("id",jobId).addValue("proof",UUID.randomUUID()).addValue("provider",job.get("provider")).addValue("ref",reference).addValue("sha",job.get("source_sha256")).addValue("snapshot",json(map(job.get("invoice_snapshot")))).addValue("outcome",outcome).addValue("response",json(proof));jdbc.update("insert into fia_proof(id,tenant_id,job_id,provider,external_reference,source_sha256,invoice_snapshot,outcome,response,actor_id) values(:proof,:tenant,:id,:provider,:ref,:sha,cast(:snapshot as jsonb),:outcome,cast(:response as jsonb),:actor)",b);jdbc.update("update fia_job set status='SUCCEEDED',outcome=:outcome,version=version+1,last_checked_at=now() where tenant_id=:tenant and id=:id",b);
   if(operation.equals("VERIFY")&&matches){var fields=snapshot(current);var legacy=Map.of("invoice_key",FinanceRules.invoiceKey(fields.get("invoiceCode").toString(),fields.get("invoiceNumber").toString()),"amount",amount(fields.get("amount")).toPlainString(),"buyer_tax_number",current.get("buyerTaxNumber"));jdbc.update("insert into finance_invoice_verification(tenant_id,invoice_id,target_kind,status,provider,external_reference,note,invoice_snapshot,actor_id) values(:tenant,:intake,'INTAKE',:legacyStatus,:provider,:ref,:note,cast(:legacy as jsonb),:actor)",b.addValue("intake",intakeId).addValue("legacyStatus",outcome.equals("VERIFIED")?"EXTERNAL_VERIFIED":"EXTERNAL_FAILED").addValue("legacy",json(legacy)).addValue("note","真实外部验证结果："+outcome+"；原件哈希"+job.get("source_sha256")+"；证明"+b.getValue("proof")));}audit.record("FINANCE_INVOICE_EXTERNAL_RESULT","FIA_JOB",jobId,json(Map.of("outcome",outcome,"matchesCurrentSource",matches,"proofId",b.getValue("proof"))));return jobs(intakeId);});}
 private void unknown(UUID job){tx.executeWithoutResult(s->{var p=principal();jdbc.update("update fia_job set status='UNKNOWN',outcome='RESULT_UNCERTAIN',version=version+1,last_checked_at=now() where tenant_id=:tenant and id=:id and status in ('PENDING','UNKNOWN')",base(p).addValue("id",job));audit.record("FINANCE_INVOICE_EXTERNAL_UNCERTAIN","FIA_JOB",job,"{}");});}
 private void failedBeforeTransmission(UUID job){tx.executeWithoutResult(s->{var p=principal();jdbc.update("update fia_job set status='FAILED',outcome='SOURCE_READ_FAILED_NOT_TRANSMITTED',version=version+1,last_checked_at=now() where tenant_id=:tenant and id=:id and status='PENDING'",base(p).addValue("id",job));audit.record("FINANCE_INVOICE_NOT_TRANSMITTED","FIA_JOB",job,"{}");});}
 private Map<String,Object> job(TenantPrincipal p,UUID intakeId,UUID job,boolean lock){var rows=jdbc.queryForList("select * from fia_job where tenant_id=:tenant and id=:id and intake_id=:intake"+(lock?" for update":""),base(p).addValue("id",job).addValue("intake",intakeId));if(rows.isEmpty())throw missing();return rows.getFirst();}
 static Map<String,Object> candidate(Map<String,Object> fields){String number=Objects.toString(fields.get("invoiceNumber"),""),code=Objects.toString(fields.get("invoiceCode"),""),tax=Objects.toString(fields.get("buyerTaxNumber"),"");if(number.length()>24||code.length()>20||tax.length()>32)throw bad("OCR候选字段超过允许长度");BigDecimal amount=null;try{if(fields.get("amount")!=null){amount=new BigDecimal(fields.get("amount").toString());if(amount.signum()<=0||amount.scale()>2||amount.precision()-amount.scale()>14)throw new IllegalArgumentException();}}catch(Exception e){throw bad("OCR候选金额格式无效");}var result=new LinkedHashMap<String,Object>();result.put("invoiceNumber",number);result.put("invoiceCode",code);result.put("buyerTaxNumber",tax);result.put("amount",amount);return result;}
 public Map<String,Object> adopt(UUID intakeId,UUID jobId,FinanceInvoiceAutomationModels.Adopt in){return tx.execute(s->{var p=principal();access.requirePermission("finance.submit");var current=intake(intakeId);if(!in.confirmCandidateAdoption()||!Boolean.TRUE.equals(current.get("canEdit")))throw conflict("仅原件所属员工可明确采纳未关联资料的OCR候选");if(((Number)current.get("version")).intValue()!=in.expectedIntakeVersion())throw conflict("收票字段已变化，请重新核对候选");var job=job(p,intakeId,jobId,true);if(!job.get("operation").equals("OCR")||!job.get("status").equals("SUCCEEDED")||!Objects.equals(current.get("sha256"),job.get("source_sha256")))throw conflict("OCR候选与当前原件不符或尚未完成");var b=base(p).addValue("id",jobId);if(jdbc.queryForObject("select count(*) from fia_adoption where tenant_id=:tenant and job_id=:id",b,Integer.class)>0)throw conflict("该OCR候选已采纳，不能重复覆盖后续人工修改");var proof=jdbc.queryForObject("select response::text from fia_proof where tenant_id=:tenant and job_id=:id",b,String.class);var fields=candidate(map(map(proof).get("candidates")));var result=finance.saveIntake(intakeId,new FinanceModels.IntakeDraft(in.expectedIntakeVersion(),fields.get("invoiceCode").toString(),fields.get("invoiceNumber").toString(),(BigDecimal)fields.get("amount"),fields.get("buyerTaxNumber").toString(),false));jdbc.update("insert into fia_adoption(tenant_id,job_id,intake_version,adopted_by) values(:tenant,:id,:version,:actor)",b.addValue("version",result.get("version")));audit.record("FINANCE_INVOICE_OCR_EXPLICITLY_ADOPTED","FIA_JOB",jobId,json(Map.of("intakeId",intakeId,"intakeVersion",result.get("version"),"confirmed",false)));return result;});}
}
